# Valeurs de départ, à ajuster par l'administrateur (seule la pénalité de charge et le délai de
# confirmation viennent du cahier des charges / du TP ; les autres sont des choix provisoires).
PARAMETRES_DE_DEPART = [
    ("penalite_charge", 3, "Coefficient du coût : pénalité par course déjà en cours (TP : 3)"),
    ("delai_confirmation_s", 30, "Temps laissé au livreur pour confirmer une course (§ 3.3)"),
    ("delai_offres_s", 3, "Temps laissé aux agents livreurs pour répondre à un appel d'offres"),
    ("rayon_recherche_initial_m", 3000, "Rayon de présélection autour de l'enlèvement"),
    ("rayon_pas_elargissement_m", 2000, "Élargissement du rayon à chaque nouvelle tentative"),
    ("tentatives_attribution_max", 3, "Appels d'offres avant d'alerter le répartiteur"),
    ("age_max_position_s", 60, "Au-delà, la position GPS est jugée trop ancienne (refus)"),
    ("tarif_fixe_xof", 500, "Part fixe du prix d'une course, en francs CFA"),
    ("tarif_km_xof", 150, "Part au kilomètre du prix d'une course, en francs CFA"),
]


def _inserer_parametres_de_depart() -> None:
    import json

    requete = sa.text(
        "INSERT INTO parametres (cle, valeur, description) "
        "VALUES (:cle, CAST(:valeur AS jsonb), :description)"
    )
    connexion = op.get_bind()
    for cle, valeur, description in PARAMETRES_DE_DEPART:
        connexion.execute(
            requete, {"cle": cle, "valeur": json.dumps(valeur), "description": description}
        )


